from donations import Donation, load_donations, ROWS
from sequence import ranked_codes


def test_nine_before_ten():
    assert ranked_codes([Donation("a", 10), Donation("b", 9)]) == ["9", "10"]


def test_mixed_lengths():
    assert ranked_codes([Donation("a", 100), Donation("b", 25), Donation("c", 9), Donation("d", 1000)]) == ["9", "25", "100", "1000"]


def test_stored():
    assert ranked_codes(list(load_donations())) == [str(v) for v in sorted(v for _, v in ROWS)]


def test_codes_are_text():
    assert all(isinstance(c, str) for c in ranked_codes(list(load_donations())))


def test_empty():
    assert ranked_codes([]) == []

